import pandas as pd
query = """
SELECT 
    "[Employee Master[Employee Name]]",
    "[Employee Master[Basic Salary]]"
FROM enterprise_data
"""
df = execute_sql_query(query)
if len(df) > 0:
    available_columns = df.columns.tolist()
    special_contract_column = '[Employee Master[Special Contract Basic Salary]]'
    if special_contract_column in available_columns:
        results = []
        for idx, row in df.iterrows():
            emp_name = row['[Employee Master[Employee Name]]']
            basic_salary = row['[Employee Master[Basic Salary]]']
            special_contract_salary = row.get(special_contract_column, None)
            if special_contract_salary is not None:
                if basic_salary != special_contract_salary:
                    results.append(f'{emp_name}: Regular Basic Salary = {basic_salary}, Special Contract Basic Salary = {special_contract_salary} (Different)')
                else:
                    results.append(f'{emp_name}: Regular Basic Salary = {basic_salary}, Special Contract Basic Salary = {special_contract_salary} (Same)')
            else:
                results.append(f'{emp_name}: Regular Basic Salary = {basic_salary}, Special Contract Basic Salary = Not recorded')
        different_salary_employees = [r for r in results if '(Different)' in r]
        if different_salary_employees:
            result = {'type': 'string', 'value': """The following employees have a Special Contract Basic Salary different from their regular Basic Salary:
""" + '\n'.join(different_salary_employees)}
        else:
            result = {'type': 'string', 'value': 'No employees found with a Special Contract Basic Salary different from their regular Basic Salary.'}
    else:
        result = {'type': 'string', 'value': f"Special Contract Basic Salary column is NOT available in the dataset. Available columns are: {', '.join(available_columns)}"}
else:
    result = {'type': 'string', 'value': 'No employee records found in the dataset.'}
result = result
